const CATEGORY_TO_GROUP: Record<string, string> = {
  Development: "developer", Data: "developer", Security: "developer", Converters: "developer", Text: "developer",
  Finance: "calculators",
  "AI Tools": "ai-writing", "AI & Business": "ai-writing", "AI & Marketing": "ai-writing", Creative: "ai-writing",
  Communication: "ai-writing", Career: "ai-writing", Business: "ai-writing", Shopping: "ai-writing",
  "Social Media": "social", Social: "social",
  Design: "design",
  "SEO & Web": "seo",
  Education: "students", Productivity: "students", Personal: "students", "Home & Life": "students",
  Health: "health", Wellness: "health",
  Utilities: "utilities",
};

export const GROUP_BY_ID: Record<string, ToolGroup> = Object.fromEntries(GROUPS.map((g) => [g.id, g]));

export function getGroup(tool: Pick<Tool, "category">): ToolGroup {
  return GROUP_BY_ID[CATEGORY_TO_GROUP[tool.category] ?? "utilities"];
}

/** Same-group tools first, then the rest of the catalogue, so every page links to several siblings. */
export function relatedTools(tool: Tool, limit = 6): Tool[] {
  const group = getGroup(tool).id;
  const siblings = tools.filter((t) => t.slug !== tool.slug && getGroup(t).id === group);
  // Start from this tool's position so different pages link to different siblings instead of all pointing at the first few.
  const start = siblings.length ? tool.id % siblings.length : 0;
  const rotated = [...siblings.slice(start), ...siblings.slice(0, start)];
  return rotated.slice(0, limit);
}

/**
 * Curated, not measured: the tools shown in the "Trending" row on the home page.
 * Edit by hand, or replace with real numbers once you have analytics.
 */
export const TRENDING_SLUGS = [
  "jwt-decoder",
  "json-formatter",
  "password-generator",
  "qr-code-generator",
  "image-compressor",
  "remove-background",
];

export const trendingTools = (): Tool[] =>
  TRENDING_SLUGS.map((slug) => tools.find((t) => t.slug === slug)).filter((t): t is Tool => !!t);
